<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Client\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Client\Domain\DynamicClientData;
use Civi\Lughauth\Features\Oidc\Client\Domain\DynamicClientRequest;
use Civi\Lughauth\Features\Oidc\Client\Domain\Exception\DynamicClientException;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\RegisterClient\RegisterClientParams;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\RegisterClient\RegisterClientResult;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\RegisterClient\RegisterClientUsecase;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\ReadDynamicClient\ReadDynamicClientUsecase;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\UpdateDynamicClient\UpdateDynamicClientUsecase;
use Civi\Lughauth\Features\Oidc\Client\Application\Usecase\DeleteDynamicClient\DeleteDynamicClientUsecase;

class DynamicClientController
{
    public function __construct(
        private readonly Context $context,
        private readonly RegisterClientUsecase $registerUsecase,
        private readonly ReadDynamicClientUsecase $readUsecase,
        private readonly UpdateDynamicClientUsecase $updateUsecase,
        private readonly DeleteDynamicClientUsecase $deleteUsecase,
    ) {
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/register',
        summary: 'Dynamic Client Registration — RFC 7591',
        description: 'Registers a new OAuth client dynamically. May require an initial_access_token depending on tenant policy.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            required: true,
            content: new OA\JsonContent(
                required: ['redirect_uris'],
                properties: [
                    new OA\Property(property: 'redirect_uris', type: 'array', items: new OA\Items(type: 'string')),
                    new OA\Property(property: 'client_name', type: 'string'),
                    new OA\Property(property: 'grant_types', type: 'array', items: new OA\Items(type: 'string')),
                    new OA\Property(property: 'response_types', type: 'array', items: new OA\Items(type: 'string')),
                    new OA\Property(property: 'scope', type: 'string'),
                    new OA\Property(property: 'token_endpoint_auth_method', type: 'string'),
                    new OA\Property(property: 'logo_uri', type: 'string'),
                    new OA\Property(property: 'backchannel_logout_uri', type: 'string'),
                ]
            )
        ),
        responses: [
            new OA\Response(response: 201, description: 'Client registered successfully'),
            new OA\Response(response: 400, description: 'Invalid client metadata'),
            new OA\Response(response: 401, description: 'initial_access_token required or invalid'),
            new OA\Response(response: 403, description: 'Registration disabled for this tenant'),
        ]
    )]
    public function post(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            $tenant = $args['tenant'];
            $body = (array) ($request->getParsedBody() ?? []);
            $initialAccessToken = $this->extractBearerToken($request);

            $registrationRequest = DynamicClientRequest::fromArray($body);

            $baseUrl = rtrim($this->context->getBaseUrl(), '/');
            $issuer = $baseUrl . '/openid/' . $tenant;

            $params = new RegisterClientParams(
                tenant: $tenant,
                issuer: $issuer,
                request: $registrationRequest,
                initialAccessToken: $initialAccessToken,
            );

            $result = $this->registerUsecase->register($params);

            $payload = $this->buildRegistrationPayload($result, $issuer);
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(201)->withHeader('Content-Type', 'application/json');
        } catch (\InvalidArgumentException $ex) {
            return $this->errorResponse($response, 'invalid_client_metadata', $ex->getMessage(), 400);
        } catch (DynamicClientException $ex) {
            return $this->errorResponse($response, $ex->error(), $ex->getMessage(), $ex->statusCode());
        }
    }

    #[OA\Get(
        path: '/oauth/openid/{tenant}/register/{client_id}',
        summary: 'Read Client Registration — RFC 7592',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'client_id', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'Client registration data'),
            new OA\Response(response: 401, description: 'Invalid registration_access_token'),
        ]
    )]
    public function get(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            $tenant = $args['tenant'];
            $clientId = $args['client_id'];
            $token = $this->requireBearerToken($request);

            $data = $this->readUsecase->read($clientId, $token);

            $baseUrl = rtrim($this->context->getBaseUrl(), '/');
            $issuer = $baseUrl . '/openid/' . $tenant;

            $payload = $this->buildClientDataPayload($data, $issuer);
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (DynamicClientException $ex) {
            return $this->errorResponse($response, $ex->error(), $ex->getMessage(), $ex->statusCode());
        }
    }

    #[OA\Put(
        path: '/oauth/openid/{tenant}/register/{client_id}',
        summary: 'Update Client Registration — RFC 7592',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'client_id', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 200, description: 'Updated client registration data'),
            new OA\Response(response: 400, description: 'Invalid client metadata'),
            new OA\Response(response: 401, description: 'Invalid registration_access_token'),
        ]
    )]
    public function put(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            $tenant = $args['tenant'];
            $clientId = $args['client_id'];
            $token = $this->requireBearerToken($request);
            $body = (array) ($request->getParsedBody() ?? []);

            $registrationRequest = DynamicClientRequest::fromArray($body);
            $data = $this->updateUsecase->update($clientId, $token, $registrationRequest);

            $baseUrl = rtrim($this->context->getBaseUrl(), '/');
            $issuer = $baseUrl . '/openid/' . $tenant;

            $payload = $this->buildClientDataPayload($data, $issuer);
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (\InvalidArgumentException $ex) {
            return $this->errorResponse($response, 'invalid_client_metadata', $ex->getMessage(), 400);
        } catch (DynamicClientException $ex) {
            return $this->errorResponse($response, $ex->error(), $ex->getMessage(), $ex->statusCode());
        }
    }

    #[OA\Delete(
        path: '/oauth/openid/{tenant}/register/{client_id}',
        summary: 'Delete Client Registration — RFC 7592',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'client_id', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 204, description: 'Client deleted'),
            new OA\Response(response: 401, description: 'Invalid registration_access_token'),
        ]
    )]
    public function delete(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            $clientId = $args['client_id'];
            $token = $this->requireBearerToken($request);

            $this->deleteUsecase->delete($clientId, $token);

            return $response->withStatus(204);
        } catch (DynamicClientException $ex) {
            return $this->errorResponse($response, $ex->error(), $ex->getMessage(), $ex->statusCode());
        }
    }

    private function buildRegistrationPayload(RegisterClientResult $result, string $issuer): array
    {
        $payload = [
            'client_id' => $result->clientId,
            'client_secret' => $result->clientSecret,
            'client_id_issued_at' => $result->clientIdIssuedAt,
            'client_secret_expires_at' => $result->clientSecretExpiresAt,
            'registration_access_token' => $result->registrationAccessToken,
            'registration_client_uri' => $result->registrationClientUri,
            'redirect_uris' => $result->request->redirectUris,
            'grant_types' => $result->request->grantTypes,
            'response_types' => $result->request->responseTypes,
            'token_endpoint_auth_method' => $result->request->tokenEndpointAuthMethod,
        ];

        return $this->addOptionalFields($payload, $result->request->clientName, $result->request->scope, $result->request->logoUri, $result->request->backchannelLogoutUri, $result->request->frontchannelLogoutUri);
    }

    private function buildClientDataPayload(DynamicClientData $data, string $issuer): array
    {
        $payload = [
            'client_id' => $data->clientId,
            'client_id_issued_at' => $data->clientIdIssuedAt,
            'registration_client_uri' => $issuer . '/register/' . $data->clientId,
            'redirect_uris' => $data->redirectUris,
            'grant_types' => $data->grantTypes,
            'response_types' => $data->responseTypes,
            'token_endpoint_auth_method' => $data->tokenEndpointAuthMethod,
        ];

        return $this->addOptionalFields($payload, $data->clientName, $data->scope, $data->logoUri, $data->backchannelLogoutUri, $data->frontchannelLogoutUri);
    }

    private function addOptionalFields(array $payload, ?string $clientName, ?string $scope, ?string $logoUri, ?string $backchannelLogoutUri, ?string $frontchannelLogoutUri): array
    {
        if ($clientName !== null) {
            $payload['client_name'] = $clientName;
        }
        if ($scope !== null) {
            $payload['scope'] = $scope;
        }
        if ($logoUri !== null) {
            $payload['logo_uri'] = $logoUri;
        }
        if ($backchannelLogoutUri !== null) {
            $payload['backchannel_logout_uri'] = $backchannelLogoutUri;
        }
        if ($frontchannelLogoutUri !== null) {
            $payload['frontchannel_logout_uri'] = $frontchannelLogoutUri;
        }
        return $payload;
    }

    private function extractBearerToken(ServerRequestInterface $request): ?string
    {
        $auth = $request->getHeaderLine('Authorization');
        if (str_starts_with($auth, 'Bearer ')) {
            return substr($auth, 7);
        }
        return null;
    }

    private function requireBearerToken(ServerRequestInterface $request): string
    {
        $token = $this->extractBearerToken($request);
        if ($token === null || $token === '') {
            throw DynamicClientException::invalidToken();
        }
        return $token;
    }

    private function errorResponse(ResponseInterface $response, string $error, string $description, int $status): ResponseInterface
    {
        $payload = ['error' => $error, 'error_description' => $description];
        $encoded = json_encode($payload);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withStatus($status)->withHeader('Content-Type', 'application/json');
    }
}
